#include <iostream>
#include <stdexcept>
long long tri(int n) {
    if (n < 0) throw std::invalid_argument("n must be nonnegative");
    if (n == 0) return 0;
    if (n == 1 || n == 2) return -1;
    return tri(n-1) + tri(n-2) + tri(n-3);
}
int main(){ int n; if(std::cin >> n) std::cout << tri(n) << '\n'; }
```

