def full_ternary_trees(n):
    if n<1 or (n-1)%3: return 0
    dp=[0]*(n+1); dp[1]=1
    for size in range(4,n+1,3):
        for a in range(1,size-1,3):
            for b in range(1,size-a-1,3):
                c=size-1-a-b
                if c>=1 and c%3==1:
                    dp[size]+=dp[a]*dp[b]*dp[c]
    return dp[n]
